    bool initializeDIRECT_DILATION_POLE_CONSTRAINT(std::string& error_message);
    bool initializeDIRECT_DILATION_SAME_Z(std::string& error_message);
    bool initializeDIRECT_DILATION_T1(std::string& error_message);
