// True iff the index multiset over the launch geometry covers every crop pixel
// exactly once (bijective onto [0, crop_w*crop_h)).
bool IndexCoversCropExactlyOnce(std::function<int(int,int,int,int,int)> index,
                                int cropW, int cropH, int blockDimX) {
    const int tile = (int)std::sqrt((double)blockDimX); // 16 for 256
    const int gx = (cropW + tile - 1) / tile;
    const int gy = (cropH + tile - 1) / tile;
    std::vector<int> seen(cropW * cropH, 0);
