            for (int t = 0; t < blockDimX; ++t) {
                int i = index(by, gx, bx, blockDimX, t);
                if (i < 0 || i >= cropW * cropH) return false;
                seen[i]++;
            }
    return std::all_of(seen.begin(), seen.end(), [](int c) { return c == 1; });
}
