**IoU reference:**

```cpp
// ---- IoU (CPU reference; encodes iou.cu) ----
// Union of the two bounding boxes, pixel-nonzero criterion (A>0 || B>0), pixels
// outside the union bbox excluded (region-restricted). Empty bbox convention =
// the renderer's inverted reset state (w-1, h-1, 0, 0).
// Reference decision (flagged deviation): IOU(∅,∅) = 1.0 — identical empty
// images are identical; the kernel divides 0/0 -> NaN (iou.cu:82-83). This is
// the spec U2/U4 must keep in sync (the CPU reference is the spec).

std::array<int, 4> BBoxOf(const std::vector<unsigned char>& img, int w, int h) {
    int left = w - 1, bottom = h - 1, right = 0, top = 0;
    for (int y = 0; y < h; ++y)
        for (int x = 0; x < w; ++x)
            if (img[y * w + x] > 0) {
                left = std::min(left, x); bottom = std::min(bottom, y);
                right = std::max(right, x); top = std::max(top, y);
            }
    // no nonzero pixels -> the renderer's inverted reset state (never a valid bbox)
    if (right < left || top < bottom) return {w - 1, h - 1, 0, 0};
    return {left, bottom, right, top};
}
double IoUReference(const std::vector<unsigned char>& A,
                    const std::vector<unsigned char>& B, int w, int h) {
    auto ba = BBoxOf(A, w, h);
    auto bb = BBoxOf(B, w, h);
    // kernel union-bbox formulas (iou.cu host, verbatim):
    int left = std::max(std::min(ba[0], bb[0]), 0);
    int bottom = std::max(std::min(ba[1], bb[1]), 0);
    int right = std::min(std::max(ba[2], bb[2]), w - 1);
    int top = std::min(std::max(ba[3], bb[3]), h - 1);
    int cw = right - left + 1;
    int ch = top - bottom + 1;
    if (cw <= 0 || ch <= 0) {
        // Degenerate crop: both bboxes empty (the only way the kernel's crop
        // inverts). Spec decision: 1.0 (identical empties), flagged deviation
        // from the kernel's 0/0 NaN.
        return 1.0;
    }
    long long inter = 0, uni = 0;
    for (int y = bottom; y <= top; ++y) {
        for (int x = left; x <= right; ++x) {
            size_t i = y * w + x;
            bool a = A[i] > 0, b = B[i] > 0;
            if (a || b) ++uni;
            if (a && b) ++inter;
        }
    }
    return (uni > 0) ? static_cast<double>(inter) / static_cast<double>(uni) : 1.0;
}
